package com.yeyamo_mobile.api.notification_service.application;
import java.time.Instant;import java.util.UUID;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.yeyamo_mobile.api.notification_service.application.port.*;import com.yeyamo_mobile.api.notification_service.domain.*;
@Service public class DevicePushTokenService{private final DevicePushTokenRepositoryPort devices;private final PreferenceRepositoryPort preferences;public DevicePushTokenService(DevicePushTokenRepositoryPort d,PreferenceRepositoryPort p){devices=d;preferences=p;}@Transactional public DevicePushToken register(String user,String token,DevicePlatform platform,String deviceId,String appVersion){Instant now=Instant.now();devices.findByToken(token).filter(existing->!existing.userId().equals(user)||!existing.deviceId().equals(deviceId)).ifPresent(existing->devices.save(new DevicePushToken(existing.id(),existing.userId(),existing.token(),existing.platform(),existing.deviceId(),existing.appVersion(),false,existing.createdAt(),now,existing.lastSeenAt(),now)));DevicePushToken current=devices.findByUserIdAndDeviceId(user,deviceId).map(existing->new DevicePushToken(existing.id(),user,token,platform,deviceId,appVersion,true,existing.createdAt(),now,now,null)).orElseGet(()->new DevicePushToken(UUID.randomUUID(),user,token,platform,deviceId,appVersion,true,now,now,now,null));var preference=preferences.find(user).orElse(NotificationPreference.defaults(user,null));preferences.save(new NotificationPreference(user,preference.inAppEnabled(),preference.emailEnabled(),true,preference.emailAddress(),token,preference.locale(),now));return devices.save(current);}@Transactional public void unregister(String user,String deviceId){devices.findByUserIdAndDeviceId(user,deviceId).ifPresent(existing->{Instant now=Instant.now();devices.save(new DevicePushToken(existing.id(),existing.userId(),existing.token(),existing.platform(),existing.deviceId(),existing.appVersion(),false,existing.createdAt(),now,existing.lastSeenAt(),now));});}@Transactional public void invalidate(String token){devices.findByToken(token).ifPresent(existing->{Instant now=Instant.now();devices.save(new DevicePushToken(existing.id(),existing.userId(),existing.token(),existing.platform(),existing.deviceId(),existing.appVersion(),false,existing.createdAt(),now,existing.lastSeenAt(),now));});}}
